package server.cashshop;

import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import server.ItemInformationProvider;

import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

/**
 * The shipped {@code cashshop/catalog.tsv} (generated by tools/cashshop/build_catalog.py) goes
 * through the real loader with nothing rejected: a row the loader drops is a row the tool thinks
 * is for sale but players never see. The WZ-side checks live in tools/cashshop/lint_catalog.py.
 */
class CashShopCatalogShippedTest {
    @BeforeAll static void initializeItemProviderWithoutExternalData() throws Exception {
        try (var db = mockStatic(tools.DatabaseConnection.class);
             var providers = mockStatic(provider.DataProviderFactory.class)) {
            var connection = mock(java.sql.Connection.class, RETURNS_DEEP_STUBS);
            db.when(tools.DatabaseConnection::getConnection).thenReturn(connection);
            providers.when(() -> provider.DataProviderFactory.getDataProvider(any(provider.wz.WZFiles.class)))
                    .thenReturn(mock(provider.DataProvider.class));
            Class.forName("server.ItemInformationProvider");
        }
    }

    @Test void loaderAcceptsEveryShippedRow() throws Exception {
        final Path shipped = Path.of("cashshop", "catalog.tsv");
        final long dataLines = Files.readAllLines(shipped).stream()
                .filter(l -> !l.isBlank() && !l.strip().startsWith("#")).count();
        final String old = System.getProperty("cashshop-path");
        System.setProperty("cashshop-path", "cashshop");
        try (var ii = mockStatic(ItemInformationProvider.class)) {
            ii.when(ItemInformationProvider::getInstance).thenReturn(mock(ItemInformationProvider.class));
            final CashShopCatalog.LoadStats s = CashShopCatalog.load();
            try {
                assertTrue(s.loaded());
                assertEquals(0, s.malformed(), "malformed rows");
                assertEquals(0, s.duplicates(), "duplicate item ids");
                assertEquals(0, s.unusable(), "rows with no inventory type or no name");
                assertEquals(dataLines, s.rows());
                for (CashShopCatalog.Row r : CashShopCatalog.all()) {
                    assertTrue(r.price() > 0, "free row " + r.itemId());
                    assertTrue(r.name().length() <= CashShopWindowPackets.MAX_NAME, "long name " + r.itemId());
                }
            } finally {
                System.setProperty("cashshop-path", Files.createTempDirectory("cs-empty").toString());
                Files.writeString(CashShopCatalog.file(), "");
                CashShopCatalog.load();                // leave the shared catalogue empty again
            }
        } finally {
            if (old == null) System.clearProperty("cashshop-path"); else System.setProperty("cashshop-path", old);
        }
    }
}
